{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_18a4a97aa6701e0012a9122b", "claim_ids": ["claim_1c5c7660a2bc5f8b700618ad", "claim_98c472a071af1305de8244b5"], "query_ids": ["q_439"], "claims": [{"claim_id": "claim_1c5c7660a2bc5f8b700618ad", "quote": "These new Section 301 tariffs would be additional to the existing 50 percent Section 301 tariff on semiconductors from China imposed pursuant to the Section 301 investigation related to forced technology transfer.", "url": "https://www.federalregister.gov/documents/2025/12/29/2025-23912/notice-of-action-chinas-acts-policies-and-practices-related-to-targeting-of-the-semiconductor", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "50 percent"}}, {"claim_id": "claim_98c472a071af1305de8244b5", "quote": "Semiconductor tariffs increased from 25% to 50%.", "url": "https://camtomx.com/en/blog/section-301-tariffs-2026-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "affected_product": "Semiconductor tariffs", "duty_rate": "50%"}}]}, {"pair_id": "conflict_f93bb52ef530c1a87e2fe9bb", "claim_ids": ["claim_3361a6b6b721048b0d3c1374", "claim_80a6cfdb4c8a9dd1ec0154c8"], "query_ids": ["q_439"], "claims": [{"claim_id": "claim_3361a6b6b721048b0d3c1374", "quote": "The United States Trade Representative (U.S. Trade Representative) has determined that China's acts, policies, and practices are actionable under Section 301 of the Trade Act of 1974 and that appropriate responsive action includes taking tariff action now on semiconductors from China, with an initial tariff level of 0 percent, increasing in 18 months on June 23, 2027, to a rate to be announced not fewer than 30 days prior to that date", "url": "https://www.federalregister.gov/documents/2025/12/29/2025-23912/notice-of-action-chinas-acts-policies-and-practices-related-to-targeting-of-the-semiconductor", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 301 of the Trade Act of 1974", "affected_product": "semiconductors from China", "duty_rate": "0 percent", "effective_date": "December 23, 2025"}}, {"claim_id": "claim_80a6cfdb4c8a9dd1ec0154c8", "quote": "Pursuant to Sections 301(b) and (c), the U.S. Trade Representative has determined that responsive action is appropriate and that appropriate responsive action includes taking tariff action now on semiconductors from China, with an initial tariff level of 0 percent, increasing in 18 months on June 23, 2027, to a rate to be announced not fewer than 30 days prior to that date.", "url": "https://www.federalregister.gov/documents/2025/12/29/2025-23912/notice-of-action-chinas-acts-policies-and-practices-related-to-targeting-of-the-semiconductor", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"effective_date": "December 23, 2025"}}]}, {"pair_id": "conflict_001b9a1355c4312350ad86d0", "claim_ids": ["claim_3562cfe9a5d9a6e89ea1816f", "claim_91555418cf392d34eb40521c"], "query_ids": ["q_441"], "claims": [{"claim_id": "claim_3562cfe9a5d9a6e89ea1816f", "quote": "Even 2-4 layer rigid PCBs, which are temporarily exempt from Section 301, still face 145% total duties - a major challenge for cost-competitive, import-reliant designs.", "url": "https://www.teamsmt.com/blog/tariffs-on-electronics-whats-exempt-and-whats-not", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "2-4 layer rigid PCBs"}}, {"claim_id": "claim_91555418cf392d34eb40521c", "quote": "The following products are still subject to the full 170% tariff burden when imported from China: - 6+ layer rigid PCBs - All other bare PCB types - Fully assembled PCBAs", "url": "https://www.teamsmt.com/blog/tariffs-on-electronics-whats-exempt-and-whats-not", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "170%"}}]}, {"pair_id": "conflict_64f28f112396035ff0d2199f", "claim_ids": ["claim_ef7adb5fcfcae09d93f35c33", "claim_fa2cb28377375f538de6e663"], "query_ids": ["q_441"], "claims": [{"claim_id": "claim_ef7adb5fcfcae09d93f35c33", "quote": "As of April 2025, most China-origin electronics are subject to multiple layers of import duties: - 25% Section 301 Tariff - 20% IEEPA Emergency Tariff - 125% Reciprocal Tariff", "url": "https://www.teamsmt.com/blog/tariffs-on-electronics-whats-exempt-and-whats-not", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "April 2025"}}, {"claim_id": "claim_fa2cb28377375f538de6e663", "quote": "| China | 30% DS/4Layer, 55% other | 14/05/25 | Until 12/11/25 | Interim deal; 90-day truce. |", "url": "https://www.icape-group.com/pcb-tariff-information", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "30% DS/4Layer, 55% other", "effective_date": "14/05/25", "expiration_date": "Until 12/11/25", "reported_policy_status": "Interim deal; 90-day truce"}}]}, {"pair_id": "conflict_39657797bcb770516d7122fc", "claim_ids": ["claim_3041d16f77e9f5291ba107a7", "claim_70dd2d47a5738698ef26d9b9"], "query_ids": ["q_442"], "claims": [{"claim_id": "claim_3041d16f77e9f5291ba107a7", "quote": "The European Commission is preparing to dramatically tighten restrictions on steel imports by cutting quotas by nearly half and doubling tariffs on excess volumes to 50%. 📝 The aggressive new measures, set to be officially unveiled on October 7, would align the European Union’s steel protection policies with tariff rates already imposed by the United States and Canada as Western allies coordinate efforts to combat massive overcapacity created by subsidized Chinese steel factories.", "url": "https://www.linkedin.com/posts/sinagolara_georgia-and-tariffs-georgia-is-a-critical-activity-7327480102080962560-gT6J", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "restrictions on steel imports", "duty_rate": "50%", "announcement_date": "October 7"}}, {"claim_id": "claim_70dd2d47a5738698ef26d9b9", "quote": "The European Commission has proposed cutting tariff-free steel import quotas by nearly half and doubling the duty on out-of-quota shipments to 50%.", "url": "https://www.linkedin.com/posts/sinagolara_georgia-and-tariffs-georgia-is-a-critical-activity-7327480102080962560-gT6J", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "cutting tariff-free steel import quotas", "duty_rate": "50%"}}]}, {"pair_id": "conflict_7b999a8e9d7da659182a2660", "claim_ids": ["claim_865368adca54e2ab484d0197", "claim_a752fc66b43c1b4db1fd3b13"], "query_ids": ["q_442"], "claims": [{"claim_id": "claim_865368adca54e2ab484d0197", "quote": "US announces 25% Tariffs on Medium & Heavy-Duty Truck Imports President Donald Trump has announced a 25% import tariff on medium- and heavy-duty trucks citing national security concerns, as posted on Truth Social. 🔹Effective Date: November 1, 2025", "url": "https://www.linkedin.com/posts/sinagolara_georgia-and-tariffs-georgia-is-a-critical-activity-7327480102080962560-gT6J", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% Tariffs on Medium & Heavy-Duty Truck Imports", "duty_rate": "25%", "effective_date": "November 1, 2025"}}, {"claim_id": "claim_a752fc66b43c1b4db1fd3b13", "quote": "🚨 News Update: US announces 25% Tariffs on Medium & Heavy-Duty Truck Imports President Donald Trump has announced a 25% import tariff on medium- and heavy-duty trucks", "url": "https://www.linkedin.com/posts/sinagolara_georgia-and-tariffs-georgia-is-a-critical-activity-7327480102080962560-gT6J", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% Tariffs on Medium & Heavy-Duty Truck Imports", "duty_rate": "25%", "effective_date": "November 1, 2025"}}]}, {"pair_id": "conflict_3615b637cc650ca57f43ac46", "claim_ids": ["claim_0e3fb75daea1ba4a1d1021b8", "claim_a113b0d861c37c46b2a72ce2"], "query_ids": ["q_443"], "claims": [{"claim_id": "claim_0e3fb75daea1ba4a1d1021b8", "quote": "Since 2019, the USTR has periodically excluded two-layer and four-layer PCBs from these tariffs due to limited domestic capacity. Those exclusions have been renewed multiple times and are now extended through May 31, 2025", "url": "https://www.teamsmt.com/blog/2025-tariffs-reshoring-ems-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_a113b0d861c37c46b2a72ce2", "quote": "For instance, knowing that a key exclusion (like the PCB tariff exclusion) is set to expire in 2025 allows your company to lobby for an extension or prepare to adjust sourcing.", "url": "https://www.teamsmt.com/blog/2025-tariffs-reshoring-ems-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "PCB tariff exclusion", "expiration_date": "2025"}}]}, {"pair_id": "conflict_7073fdc69c3e9c4afce7a092", "claim_ids": ["claim_3a1d3796cb25c1e72b5e70ec", "claim_99b6915b79338f62ee8450f5"], "query_ids": ["q_443"], "claims": [{"claim_id": "claim_3a1d3796cb25c1e72b5e70ec", "quote": "Post-2024 election, the incoming U.S. administration floated a proposal for a 10% universal import tariff in February 2025, which is still under debate as of March.", "url": "https://www.teamsmt.com/blog/2025-tariffs-reshoring-ems-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "10% universal import tariff", "announcement_date": "February 2025", "reported_policy_status": "still under debate as of March"}}, {"claim_id": "claim_99b6915b79338f62ee8450f5", "quote": "The 2024 U.S. election cycle featured proposals for across-the-board tariffs on imports (e.g., a blanket 10% tariff on all imports was floated).", "url": "https://www.teamsmt.com/blog/2025-tariffs-reshoring-ems-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "across-the-board tariffs on imports", "duty_rate": "10%"}}]}, {"pair_id": "conflict_f26c677ebfa0500302f98fa2", "claim_ids": ["claim_7b4d307f5c8b10bbd6ad67d8", "claim_7c03a556834df3b0ff2c7ad7"], "query_ids": ["q_444"], "claims": [{"claim_id": "claim_7b4d307f5c8b10bbd6ad67d8", "quote": "Under the ongoing U.S.-China trade tensions, a large share of these electronics components from China carry 25% or higher tariffs (some categories were previously 10%, now lifted to 25%).", "url": "https://www.bluebayautomation.com/blog/automation-news-updates-11/impact-of-tariffs-on-u-s-smb-manufacturers-103", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25% or higher"}}, {"claim_id": "claim_7c03a556834df3b0ff2c7ad7", "quote": "Chinese imports now face a minimum 54% duty, with even higher rates if the product is also subject to metal or automotive tariffs.", "url": "https://www.bluebayautomation.com/blog/automation-news-updates-11/impact-of-tariffs-on-u-s-smb-manufacturers-103", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "China-specific tariffs", "duty_rate": "minimum 54%"}}]}, {"pair_id": "conflict_f971e45d33b145785316303d", "claim_ids": ["claim_1d3c0463abe24d8798e50739", "claim_b358192358f2218f72526864"], "query_ids": ["q_444"], "claims": [{"claim_id": "claim_1d3c0463abe24d8798e50739", "quote": "Importers of automobiles under the United States-Mexico-Canada Agreement will be given the opportunity to certify their U.S. content and systems will be implemented such that the 25% tariff will only apply to the value of their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "United States-Mexico-Canada Agreement"}}, {"claim_id": "claim_b358192358f2218f72526864", "quote": "USMCA-compliant automobile parts will remain tariff-free until the Secretary of Commerce, in consultation with U.S. Customs and Border Protection (CBP), establishes a process to apply tariffs to their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "USMCA"}}]}]}

